UPDATE cms_slot_translation cst
JOIN cms_slot s ON s.id = cst.cms_slot_id AND s.version_id = cst.cms_slot_version_id
JOIN cms_block b ON b.id = s.cms_block_id AND b.version_id = s.cms_block_version_id
JOIN cms_section sec ON sec.id = b.cms_section_id AND sec.version_id = b.cms_section_version_id
JOIN system_config sc ON UNHEX(JSON_UNQUOTE(JSON_EXTRACT(sc.configuration_value, '$._value'))) = sec.cms_page_id
SET cst.config = JSON_SET(cst.config, '$.content.value', '<h2>Impressum</h2><hr /><h3>Angaben gemäß § 5 DDG</h3><p>Yohane Gruber<br />Goethestrasse 78<br />97493 Bergrheinfeld<br />Deutschland</p><h3>Kontakt</h3><p>E-Mail: hello@yoxa.eu</p><h3>Umsatzsteuer</h3><p>Als Kleinunternehmer im Sinne von § 19 Abs. 1 UStG weisen wir keine Umsatzsteuer aus. Eine Umsatzsteuer-Identifikationsnummer gemäß § 27a UStG ist daher nicht vorhanden.</p><h3>EU-Streitschlichtung</h3><p>Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: <a href="https://ec.europa.eu/consumers/odr">https://ec.europa.eu/consumers/odr</a>. Unsere E-Mail-Adresse finden Sie oben im Impressum.</p><h3>Verbraucherstreitbeilegung / Universalschlichtungsstelle</h3><p>Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.</p>')
WHERE sc.configuration_key = 'core.basicInformation.imprintPage'
AND cst.language_id = UNHEX('d9712b5552674d669aeecd16a191373a')
AND JSON_EXTRACT(cst.config, '$.content.value') IS NOT NULL
AND JSON_UNQUOTE(JSON_EXTRACT(cst.config, '$.content.value')) <> '<h2>Impressum</h2><hr /><h3>Angaben gemäß § 5 DDG</h3><p>Yohane Gruber<br />Goethestrasse 78<br />97493 Bergrheinfeld<br />Deutschland</p><h3>Kontakt</h3><p>E-Mail: hello@yoxa.eu</p><h3>Umsatzsteuer</h3><p>Als Kleinunternehmer im Sinne von § 19 Abs. 1 UStG weisen wir keine Umsatzsteuer aus. Eine Umsatzsteuer-Identifikationsnummer gemäß § 27a UStG ist daher nicht vorhanden.</p><h3>EU-Streitschlichtung</h3><p>Die Europäische Kommission stellt eine Plattform zur Online-Streitbeilegung (OS) bereit: <a href="https://ec.europa.eu/consumers/odr">https://ec.europa.eu/consumers/odr</a>. Unsere E-Mail-Adresse finden Sie oben im Impressum.</p><h3>Verbraucherstreitbeilegung / Universalschlichtungsstelle</h3><p>Wir sind nicht bereit und nicht verpflichtet, an Streitbeilegungsverfahren vor einer Verbraucherschlichtungsstelle teilzunehmen.</p>';

UPDATE cms_slot_translation cst
JOIN cms_slot s ON s.id = cst.cms_slot_id AND s.version_id = cst.cms_slot_version_id
JOIN cms_block b ON b.id = s.cms_block_id AND b.version_id = s.cms_block_version_id
JOIN cms_section sec ON sec.id = b.cms_section_id AND sec.version_id = b.cms_section_version_id
JOIN system_config sc ON UNHEX(JSON_UNQUOTE(JSON_EXTRACT(sc.configuration_value, '$._value'))) = sec.cms_page_id
SET cst.config = JSON_SET(cst.config, '$.content.value', '<h2>Imprint</h2><hr /><h3>Information according to Section 5 DDG (German Digital Services Act)</h3><p>Yohane Gruber<br />Goethestrasse 78<br />97493 Bergrheinfeld<br />Germany</p><h3>Contact</h3><p>Email: hello@yoxa.eu</p><h3>Value added tax</h3><p>As a small business within the meaning of Section 19 (1) UStG (German Small Business Regulation), we do not show VAT. A VAT identification number according to Section 27a UStG therefore does not exist.</p><h3>EU dispute resolution</h3><p>The European Commission provides a platform for online dispute resolution (ODR): <a href="https://ec.europa.eu/consumers/odr">https://ec.europa.eu/consumers/odr</a>. You can find our email address in the imprint above.</p><h3>Consumer dispute resolution / universal arbitration board</h3><p>We are not willing or obliged to participate in dispute resolution proceedings before a consumer arbitration board.</p>')
WHERE sc.configuration_key = 'core.basicInformation.imprintPage'
AND cst.language_id = UNHEX('2fbb5fe2e29a4d70aa5854ce7ce3e20b')
AND JSON_EXTRACT(cst.config, '$.content.value') IS NOT NULL
AND JSON_UNQUOTE(JSON_EXTRACT(cst.config, '$.content.value')) <> '<h2>Imprint</h2><hr /><h3>Information according to Section 5 DDG (German Digital Services Act)</h3><p>Yohane Gruber<br />Goethestrasse 78<br />97493 Bergrheinfeld<br />Germany</p><h3>Contact</h3><p>Email: hello@yoxa.eu</p><h3>Value added tax</h3><p>As a small business within the meaning of Section 19 (1) UStG (German Small Business Regulation), we do not show VAT. A VAT identification number according to Section 27a UStG therefore does not exist.</p><h3>EU dispute resolution</h3><p>The European Commission provides a platform for online dispute resolution (ODR): <a href="https://ec.europa.eu/consumers/odr">https://ec.europa.eu/consumers/odr</a>. You can find our email address in the imprint above.</p><h3>Consumer dispute resolution / universal arbitration board</h3><p>We are not willing or obliged to participate in dispute resolution proceedings before a consumer arbitration board.</p>';

-- ===========================================================================
-- Widerruf / Right of rescission
-- ===========================================================================

UPDATE cms_slot_translation cst
JOIN cms_slot s ON s.id = cst.cms_slot_id AND s.version_id = cst.cms_slot_version_id
JOIN cms_block b ON b.id = s.cms_block_id AND b.version_id = s.cms_block_version_id
JOIN cms_section sec ON sec.id = b.cms_section_id AND sec.version_id = b.cms_section_version_id
JOIN system_config sc ON UNHEX(JSON_UNQUOTE(JSON_EXTRACT(sc.configuration_value, '$._value'))) = sec.cms_page_id
SET cst.config = JSON_SET(cst.config, '$.content.value', '<h2>Widerruf</h2><hr /><h3>Widerrufsbelehrung</h3><h4>Widerrufsrecht</h4><p>Sie haben das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen. Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag, an dem Sie oder ein von Ihnen benannter Dritter, der nicht der Beförderer ist, die letzte Ware in Besitz genommen haben bzw. hat.</p><p>Um Ihr Widerrufsrecht auszuüben, müssen Sie uns (Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Deutschland, E-Mail: hello@yoxa.eu) mittels einer eindeutigen Erklärung (z. B. ein mit der Post versandter Brief oder eine E-Mail) über Ihren Entschluss, diesen Vertrag zu widerrufen, informieren. Sie können dafür das beigefügte Muster-Widerrufsformular verwenden, das jedoch nicht vorgeschrieben ist.</p><p>Zur Wahrung der Widerrufsfrist reicht es aus, dass Sie die Mitteilung über die Ausübung des Widerrufsrechts vor Ablauf der Widerrufsfrist absenden.</p><h4>Folgen des Widerrufs</h4><p>Wenn Sie diesen Vertrag widerrufen, haben wir Ihnen alle Zahlungen, die wir von Ihnen erhalten haben, einschließlich der Lieferkosten (mit Ausnahme der zusätzlichen Kosten, die sich daraus ergeben, dass Sie eine andere Art der Lieferung als die von uns angebotene, günstigste Standardlieferung gewählt haben), unverzüglich und spätestens binnen vierzehn Tagen ab dem Tag zurückzuzahlen, an dem die Mitteilung über Ihren Widerruf dieses Vertrags bei uns eingegangen ist. Für diese Rückzahlung verwenden wir dasselbe Zahlungsmittel, das Sie bei der ursprünglichen Transaktion eingesetzt haben, es sei denn, mit Ihnen wurde ausdrücklich etwas anderes vereinbart; in keinem Fall werden Ihnen wegen dieser Rückzahlung Entgelte berechnet. Wir können die Rückzahlung verweigern, bis wir die Waren wieder zurückerhalten haben oder bis Sie den Nachweis erbracht haben, dass Sie die Waren zurückgesandt haben, je nachdem, welches der frühere Zeitpunkt ist.</p><p>Sie haben die Waren unverzüglich und in jedem Fall spätestens binnen vierzehn Tagen ab dem Tag, an dem Sie uns über den Widerruf dieses Vertrags unterrichten, an uns zurückzusenden oder zu übergeben. Die Frist ist gewahrt, wenn Sie die Waren vor Ablauf der Frist von vierzehn Tagen absenden. Sie tragen die unmittelbaren Kosten der Rücksendung der Waren. Sie müssen für einen etwaigen Wertverlust der Waren nur aufkommen, wenn dieser Wertverlust auf einen zur Prüfung der Beschaffenheit, Eigenschaften und Funktionsweise der Waren nicht notwendigen Umgang mit ihnen zurückzuführen ist.</p><h4>Muster-Widerrufsformular</h4><p>(Wenn Sie den Vertrag widerrufen wollen, dann füllen Sie bitte dieses Formular aus und senden Sie es zurück.)</p><p>– An: Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Deutschland, E-Mail: hello@yoxa.eu<br />– Hiermit widerrufe(n) ich/wir (*) den von mir/uns (*) abgeschlossenen Vertrag über den Kauf der folgenden Waren (*)<br />– Bestellt am (*) / erhalten am (*)<br />– Name des/der Verbraucher(s)<br />– Anschrift des/der Verbraucher(s)<br />– Unterschrift des/der Verbraucher(s) (nur bei Mitteilung auf Papier)<br />– Datum</p><p>(*) Unzutreffendes streichen.</p>')
WHERE sc.configuration_key = 'core.basicInformation.revocationPage'
AND cst.language_id = UNHEX('d9712b5552674d669aeecd16a191373a')
AND JSON_EXTRACT(cst.config, '$.content.value') IS NOT NULL
AND JSON_UNQUOTE(JSON_EXTRACT(cst.config, '$.content.value')) <> '<h2>Widerruf</h2><hr /><h3>Widerrufsbelehrung</h3><h4>Widerrufsrecht</h4><p>Sie haben das Recht, binnen vierzehn Tagen ohne Angabe von Gründen diesen Vertrag zu widerrufen. Die Widerrufsfrist beträgt vierzehn Tage ab dem Tag, an dem Sie oder ein von Ihnen benannter Dritter, der nicht der Beförderer ist, die letzte Ware in Besitz genommen haben bzw. hat.</p><p>Um Ihr Widerrufsrecht auszuüben, müssen Sie uns (Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Deutschland, E-Mail: hello@yoxa.eu) mittels einer eindeutigen Erklärung (z. B. ein mit der Post versandter Brief oder eine E-Mail) über Ihren Entschluss, diesen Vertrag zu widerrufen, informieren. Sie können dafür das beigefügte Muster-Widerrufsformular verwenden, das jedoch nicht vorgeschrieben ist.</p><p>Zur Wahrung der Widerrufsfrist reicht es aus, dass Sie die Mitteilung über die Ausübung des Widerrufsrechts vor Ablauf der Widerrufsfrist absenden.</p><h4>Folgen des Widerrufs</h4><p>Wenn Sie diesen Vertrag widerrufen, haben wir Ihnen alle Zahlungen, die wir von Ihnen erhalten haben, einschließlich der Lieferkosten (mit Ausnahme der zusätzlichen Kosten, die sich daraus ergeben, dass Sie eine andere Art der Lieferung als die von uns angebotene, günstigste Standardlieferung gewählt haben), unverzüglich und spätestens binnen vierzehn Tagen ab dem Tag zurückzuzahlen, an dem die Mitteilung über Ihren Widerruf dieses Vertrags bei uns eingegangen ist. Für diese Rückzahlung verwenden wir dasselbe Zahlungsmittel, das Sie bei der ursprünglichen Transaktion eingesetzt haben, es sei denn, mit Ihnen wurde ausdrücklich etwas anderes vereinbart; in keinem Fall werden Ihnen wegen dieser Rückzahlung Entgelte berechnet. Wir können die Rückzahlung verweigern, bis wir die Waren wieder zurückerhalten haben oder bis Sie den Nachweis erbracht haben, dass Sie die Waren zurückgesandt haben, je nachdem, welches der frühere Zeitpunkt ist.</p><p>Sie haben die Waren unverzüglich und in jedem Fall spätestens binnen vierzehn Tagen ab dem Tag, an dem Sie uns über den Widerruf dieses Vertrags unterrichten, an uns zurückzusenden oder zu übergeben. Die Frist ist gewahrt, wenn Sie die Waren vor Ablauf der Frist von vierzehn Tagen absenden. Sie tragen die unmittelbaren Kosten der Rücksendung der Waren. Sie müssen für einen etwaigen Wertverlust der Waren nur aufkommen, wenn dieser Wertverlust auf einen zur Prüfung der Beschaffenheit, Eigenschaften und Funktionsweise der Waren nicht notwendigen Umgang mit ihnen zurückzuführen ist.</p><h4>Muster-Widerrufsformular</h4><p>(Wenn Sie den Vertrag widerrufen wollen, dann füllen Sie bitte dieses Formular aus und senden Sie es zurück.)</p><p>– An: Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Deutschland, E-Mail: hello@yoxa.eu<br />– Hiermit widerrufe(n) ich/wir (*) den von mir/uns (*) abgeschlossenen Vertrag über den Kauf der folgenden Waren (*)<br />– Bestellt am (*) / erhalten am (*)<br />– Name des/der Verbraucher(s)<br />– Anschrift des/der Verbraucher(s)<br />– Unterschrift des/der Verbraucher(s) (nur bei Mitteilung auf Papier)<br />– Datum</p><p>(*) Unzutreffendes streichen.</p>';

UPDATE cms_slot_translation cst
JOIN cms_slot s ON s.id = cst.cms_slot_id AND s.version_id = cst.cms_slot_version_id
JOIN cms_block b ON b.id = s.cms_block_id AND b.version_id = s.cms_block_version_id
JOIN cms_section sec ON sec.id = b.cms_section_id AND sec.version_id = b.cms_section_version_id
JOIN system_config sc ON UNHEX(JSON_UNQUOTE(JSON_EXTRACT(sc.configuration_value, '$._value'))) = sec.cms_page_id
SET cst.config = JSON_SET(cst.config, '$.content.value', '<h2>Right of rescission</h2><hr /><h3>Cancellation policy</h3><h4>Right of withdrawal</h4><p>You have the right to withdraw from this contract within fourteen days without giving any reason. The withdrawal period is fourteen days from the day on which you or a third party named by you, who is not the carrier, took possession of the last goods.</p><p>To exercise your right of withdrawal, you must inform us (Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Germany, email: hello@yoxa.eu) of your decision to withdraw from this contract by means of a clear statement (e.g. a letter sent by post or an email). You may use the attached model withdrawal form, but it is not mandatory.</p><p>To meet the withdrawal deadline, it is sufficient for you to send your communication concerning your exercise of the right of withdrawal before the withdrawal period has expired.</p><h4>Effects of withdrawal</h4><p>If you withdraw from this contract, we shall reimburse to you all payments received from you, including the costs of delivery (with the exception of the supplementary costs resulting from your choice of a type of delivery other than the least expensive type of standard delivery offered by us), without undue delay and in any event not later than fourteen days from the day on which we are informed about your decision to withdraw from this contract. We will carry out such reimbursement using the same means of payment as you used for the initial transaction, unless you have expressly agreed otherwise; in any event, you will not incur any fees as a result of such reimbursement. We may withhold reimbursement until we have received the goods back or you have supplied evidence of having sent back the goods, whichever is the earliest.</p><p>You shall send back the goods or hand them over to us without undue delay and in any event not later than fourteen days from the day on which you communicate your withdrawal from this contract to us. The deadline is met if you send back the goods before the period of fourteen days has expired. You will have to bear the direct cost of returning the goods. You are only liable for any diminished value of the goods resulting from the handling other than what is necessary to establish the nature, characteristics and functioning of the goods.</p><h4>Model withdrawal form</h4><p>(Complete and return this form only if you wish to withdraw from the contract.)</p><p>– To: Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Germany, email: hello@yoxa.eu<br />– I/We (*) hereby give notice that I/We (*) withdraw from my/our (*) contract of sale of the following goods (*)<br />– Ordered on (*) / received on (*)<br />– Name of consumer(s)<br />– Address of consumer(s)<br />– Signature of consumer(s) (only if this form is notified on paper)<br />– Date</p><p>(*) Delete as appropriate.</p>')
WHERE sc.configuration_key = 'core.basicInformation.revocationPage'
AND cst.language_id = UNHEX('2fbb5fe2e29a4d70aa5854ce7ce3e20b')
AND JSON_EXTRACT(cst.config, '$.content.value') IS NOT NULL
AND JSON_UNQUOTE(JSON_EXTRACT(cst.config, '$.content.value')) <> '<h2>Right of rescission</h2><hr /><h3>Cancellation policy</h3><h4>Right of withdrawal</h4><p>You have the right to withdraw from this contract within fourteen days without giving any reason. The withdrawal period is fourteen days from the day on which you or a third party named by you, who is not the carrier, took possession of the last goods.</p><p>To exercise your right of withdrawal, you must inform us (Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Germany, email: hello@yoxa.eu) of your decision to withdraw from this contract by means of a clear statement (e.g. a letter sent by post or an email). You may use the attached model withdrawal form, but it is not mandatory.</p><p>To meet the withdrawal deadline, it is sufficient for you to send your communication concerning your exercise of the right of withdrawal before the withdrawal period has expired.</p><h4>Effects of withdrawal</h4><p>If you withdraw from this contract, we shall reimburse to you all payments received from you, including the costs of delivery (with the exception of the supplementary costs resulting from your choice of a type of delivery other than the least expensive type of standard delivery offered by us), without undue delay and in any event not later than fourteen days from the day on which we are informed about your decision to withdraw from this contract. We will carry out such reimbursement using the same means of payment as you used for the initial transaction, unless you have expressly agreed otherwise; in any event, you will not incur any fees as a result of such reimbursement. We may withhold reimbursement until we have received the goods back or you have supplied evidence of having sent back the goods, whichever is the earliest.</p><p>You shall send back the goods or hand them over to us without undue delay and in any event not later than fourteen days from the day on which you communicate your withdrawal from this contract to us. The deadline is met if you send back the goods before the period of fourteen days has expired. You will have to bear the direct cost of returning the goods. You are only liable for any diminished value of the goods resulting from the handling other than what is necessary to establish the nature, characteristics and functioning of the goods.</p><h4>Model withdrawal form</h4><p>(Complete and return this form only if you wish to withdraw from the contract.)</p><p>– To: Yohane Gruber, Goethestrasse 78, 97493 Bergrheinfeld, Germany, email: hello@yoxa.eu<br />– I/We (*) hereby give notice that I/We (*) withdraw from my/our (*) contract of sale of the following goods (*)<br />– Ordered on (*) / received on (*)<br />– Name of consumer(s)<br />– Address of consumer(s)<br />– Signature of consumer(s) (only if this form is notified on paper)<br />– Date</p><p>(*) Delete as appropriate.</p>';
